#include <iostream>
#include <vector>
using namespace std;

class Stack {
private:
    vector<int> items;

public:
    void push(int item) {
        items.push_back(item);
    }

    int pop() {
        if (!isEmpty()) {
            int top = items.back();
            items.pop_back();
            return top;
        }
        return -1;
    }

    int peek() {
        if (!isEmpty()) return items.back();
        return -1;
    }

    bool isEmpty() {
        return items.empty();
    }

    int size() {
        return items.size();
    }
};

int main() {
    Stack stack;
    stack.push(1);
    stack.push(2);
    stack.push(3);

    cout << "栈顶元素: " << stack.peek() << endl;
    cout << "弹出元素: " << stack.pop() << endl;
    cout << "栈的大小: " << stack.size() << endl;

    return 0;
}
